// Connect to mongosh as admin first
// (locally without auth enabled yet)

// Step 1: Create the admin user FIRST (before enabling auth)
use admin
db.createUser({
  user: 'admin',
  pwd: 'UseAStrongPasswordHere!2026',
  roles: [
    { role: 'userAdminAnyDatabase', db: 'admin' },
    { role: 'readWriteAnyDatabase', db: 'admin' },
    { role: 'clusterAdmin', db: 'admin' }
  ]
});

// Step 2: Create a least-privilege application user
use myapp
db.createUser({
  user: 'appuser',
  pwd: 'AnotherStrongPassword2026!',
  roles: [
    { role: 'readWrite', db: 'myapp' }  // only readWrite on myapp — nothing else!
  ]
});

// Step 3: Create a read-only reporting user
db.createUser({
  user: 'reporter',
  pwd: 'ReportingPassword2026!',
  roles: [
    { role: 'read', db: 'myapp' }  // read-only — cannot insert/update/delete
  ]
});

// Built-in roles (from least to most privileged)

// Database-level roles:
// 'read'           — find() and aggregate on the specified database
// 'readWrite'      — read + insert, update, delete, createCollection
// 'dbAdmin'        — manage indexes, explain, rename collections
// 'userAdmin'      — create/modify users (for the specified database only)

// Cluster-level roles:
// 'clusterMonitor' — read-only cluster stats
// 'clusterAdmin'   — full cluster management (sharding, replication)

// All-database roles (applied to 'admin' db):
// 'readAnyDatabase', 'readWriteAnyDatabase', 'userAdminAnyDatabase'

// Create a custom role with fine-grained permissions
use admin
db.createRole({
  role: 'analyticsReader',
  privileges: [
    {
      resource: { db: 'myapp', collection: 'orders' },
      actions: ['find', 'aggregate']  // only these two actions
    }
  ],
  roles: []  // no inherited roles
});

// Assign the custom role
db.grantRolesToUser('analyst_user', [
  { role: 'analyticsReader', db: 'admin' }
]);

// Store credentials in environment variables — NEVER hardcode
const uri = process.env.MONGODB_URI;
// MONGODB_URI=mongodb://appuser:password@host:27017/myapp?authSource=myapp

// Connection options for production
const client = new MongoClient(uri, {
  tls: true,
  tlsCAFile: '/path/to/ca.pem',    // verify server certificate
  serverSelectionTimeoutMS: 5000,  // fail fast if no server available
  socketTimeoutMS: 45000,

  // Connection pool settings for production
  maxPoolSize: 50,       // max concurrent connections
  minPoolSize: 5,        // keep 5 connections warm
  maxIdleTimeMS: 30000,  // close idle connections after 30s
});

// Atlas connection string already includes TLS by default
const atlasUri = process.env.ATLAS_URI;
